--
-- Name: pgrst_ddl_watch(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.pgrst_ddl_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()
  LOOP
    IF cmd.command_tag IN (
      'CREATE SCHEMA', 'ALTER SCHEMA'
    , 'CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO', 'ALTER TABLE'
    , 'CREATE FOREIGN TABLE', 'ALTER FOREIGN TABLE'
    , 'CREATE VIEW', 'ALTER VIEW'
    , 'CREATE MATERIALIZED VIEW', 'ALTER MATERIALIZED VIEW'
    , 'CREATE FUNCTION', 'ALTER FUNCTION'
    , 'CREATE TRIGGER'
    , 'CREATE TYPE', 'ALTER TYPE'
    , 'CREATE RULE'
    , 'COMMENT'
    )
    -- don't notify in case of CREATE TEMP table or other objects created on pg_temp
    AND cmd.schema_name is distinct from 'pg_temp'
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


ALTER FUNCTION extensions.pgrst_ddl_watch() OWNER TO supabase_admin;

--
-- Name: pgrst_drop_watch(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.pgrst_drop_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  obj record;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()
  LOOP
    IF obj.object_type IN (
      'schema'
    , 'table'
    , 'foreign table'
    , 'view'
    , 'materialized view'
    , 'function'
    , 'trigger'
    , 'type'
    , 'rule'
    )
    AND obj.is_temporary IS false -- no pg_temp objects
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


ALTER FUNCTION extensions.pgrst_drop_watch() OWNER TO supabase_admin;

--
-- Name: set_graphql_placeholder(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.set_graphql_placeholder() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
    DECLARE
    graphql_is_dropped bool;
    BEGIN
    graphql_is_dropped = (
        SELECT ev.schema_name = 'graphql_public'
        FROM pg_event_trigger_dropped_objects() AS ev
        WHERE ev.schema_name = 'graphql_public'
    );

    IF graphql_is_dropped
    THEN
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language plpgsql
        as $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;
    END IF;

    END;
$_$;


ALTER FUNCTION extensions.set_graphql_placeholder() OWNER TO supabase_admin;

--
-- Name: FUNCTION set_graphql_placeholder(); Type: COMMENT; Schema: extensions; Owner: supabase_admin
--

COMMENT ON FUNCTION extensions.set_graphql_placeholder() IS 'Reintroduces placeholder function for graphql_public.graphql';


--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
begin
    raise debug 'PgBouncer auth request: %', p_usename;

    return query
    select 
        rolname::text, 
        case when rolvaliduntil < now() 
            then null 
            else rolpassword::text 
        end 
    from pg_authid 
    where rolname=$1 and rolcanlogin;
end;
$_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: can_close_customer_account(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_close_customer_account(p_customer_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    total_repaid NUMERIC;
    amount_given NUMERIC;
BEGIN
    SELECT 
        COALESCE(SUM(CASE WHEN t.transaction_type = 'repayment' THEN t.amount ELSE 0 END), 0) AS total_repaid,
        COALESCE(c.amount_given, 0) AS amount_given
    INTO total_repaid, amount_given
    FROM customers c
    LEFT JOIN transactions t ON t.customer_id = c.id
    WHERE c.id = p_customer_id
    GROUP BY c.amount_given;

    RETURN amount_given <= total_repaid;
END;
$$;


ALTER FUNCTION public.can_close_customer_account(p_customer_id uuid) OWNER TO postgres;

--
-- Name: get_area_wise_summary(uuid, double precision, double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_area_wise_summary(user_id_param uuid, latitude_param double precision, longitude_param double precision) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    total_amount NUMERIC;
BEGIN
    SELECT SUM(amount)
    INTO total_amount
    FROM transactions
    WHERE
        user_id = user_id_param AND
        ST_DWithin(
            ST_MakePoint(longitude, latitude)::geography,
            ST_MakePoint(longitude_param, latitude_param)::geography,
            5000 -- Radius in meters
        );

    RETURN COALESCE(total_amount, 0);
END;
$$;


ALTER FUNCTION public.get_area_wise_summary(user_id_param uuid, latitude_param double precision, longitude_param double precision) OWNER TO postgres;

--
-- Name: get_customer_payment_status_for_csv(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_customer_payment_status_for_csv(p_area_id bigint) RETURNS TABLE(customer_id bigint, area_name character varying, card_no text, payment_status text, "totalAmountReceived" numeric, customer_name text, mobile text, email text, start_date date, end_date date, days_to_complete integer, expected_repayment_amount numeric, repayment_frequency character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        c.id::BIGINT,
        am.area_name::VARCHAR,
        c.book_no::TEXT,
        CASE
            WHEN EXISTS (
                SELECT 1
                FROM public.transactions t_today
                WHERE t_today.customer_id = c.id
                  AND t_today.transaction_type = 'repayment'
                  AND t_today.created_at::date = NOW()::date
            ) THEN 'Paid Today'::TEXT
            ELSE 'Not Paid Today'::TEXT
        END,
        COALESCE(t.total_amount, 0)::NUMERIC,
        c.name::TEXT,
        c.mobile::TEXT,
        c.email::TEXT,
        c.start_date::DATE,
        c.end_date::DATE,
        c.days_to_complete::INTEGER,
        c.repayment_amount::NUMERIC,
        c.repayment_frequency::VARCHAR
    FROM public.customers c
    LEFT JOIN public.area_master am ON c.area_id = am.id
    LEFT JOIN (
        SELECT
            t.customer_id,
            SUM(t.amount) as total_amount
        FROM public.transactions t
        WHERE t.transaction_type = 'repayment'
        GROUP BY t.customer_id
    ) t ON c.id = t.customer_id
    WHERE c.area_id = p_area_id;
END;
$$;


ALTER FUNCTION public.get_customer_payment_status_for_csv(p_area_id bigint) OWNER TO postgres;

--
-- Name: get_daily_payment_summary(bigint, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_daily_payment_summary(p_area_id bigint, p_date date) RETURNS TABLE(payment_mode text, total_amount numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        t.payment_mode::text,
        SUM(t.amount) AS total_amount
    FROM
        public.transactions t
    JOIN
        public.customers c ON t.customer_id = c.id
    WHERE
        c.area_id = p_area_id
        AND t.transaction_date::date = p_date
    GROUP BY
        t.payment_mode;
END;
$$;


ALTER FUNCTION public.get_daily_payment_summary(p_area_id bigint, p_date date) OWNER TO postgres;

